    """
    Function to answer the query "man on the right".
    """
    # Split the query into words
    query_words = query.split()

    # Find the man patches
    man_patches = image_patch.find("man")

    # If no man is found, return "No man found"
    if not man_patches:
        return "No man found"

    # Sort the man patches by their left edge (from left to right)
    man_patches.sort(key=lambda man: man.left)

    # If the query asks about the man on the right, return the last man patch
    if query_words[-1].lower() == "right":
        return str(man_patches[-1])

    # If the query asks about the man on the left, return the first man patch
    elif query_words[-1].lower() == "left":
        return str(man_patches[0])

    # If the query is not clear, return "Query not clear"
    else:
        return "Query not clear"

